(async()=>{
  // 用 j0001 的真实部件合成原图：网格分散摆放，格子大于最大部件，保证不粘连
  const d = await (await fetch('/api/character/j0001')).json();
  const ps = d.parts.filter(p=>p.active && p.imgUrl);
  const imgs = [];
  for (const p of ps) {
    const im = new Image();
    await new Promise(r=>{ im.onload=r; im.onerror=r; im.src=p.imgUrl; });
    imgs.push({ name:p.attachment, im });
  }
  let mx=0; for(const it of imgs) mx=Math.max(mx,it.im.naturalWidth,it.im.naturalHeight);
  const cell=mx+40;
  const cols=5, rows=Math.ceil(imgs.length/cols);
  const W=cols*cell, H=rows*cell;
  const cv=document.createElement('canvas'); cv.width=W; cv.height=H;
  const g=cv.getContext('2d');
  const placed=[];
  imgs.forEach((it,i)=>{
    const c=i%cols, r=Math.floor(i/cols);
    const x=c*cell+20, y=r*cell+20;
    g.drawImage(it.im, x, y);
    placed.push({name:it.name, x, y, w:it.im.naturalWidth, h:it.im.naturalHeight});
  });
  window.__testImg = cv.toDataURL('image/png');
  window.__placed = placed;
  return '原图 '+W+'x'+H+' cell='+cell+'（最大部件 '+mx+'）· 摆放 '+placed.length+' 个';
})()

(async()=>{
  const E=window.CutterEngine;
  const img=new Image();
  await new Promise(r=>{img.onload=r;img.src=window.__testImg;});
  E.loadImage(img,'test_grid2');
  const r = E.autoSplit('alpha',{minArea:60,alphaThreshold:8});
  const got = E.orderedParts().map(p=>p.bbox.x+','+p.bbox.y+' '+p.bbox.w+'x'+p.bbox.h).sort();
  const exp = window.__placed.map(p=>p.x+','+p.y+' '+p.w+'x'+p.h).sort();
  const same = JSON.stringify(got)===JSON.stringify(exp);
  window.__got=got; window.__exp=exp;
  return '切分='+r.note+'（期望 '+window.__placed.length+' 块）\n  逐块比对='+same+(same?'':'\n  got:'+got.join('|')+'\n  exp:'+exp.join('|'));
})()

(()=>{
  const E=window.CutterEngine;
  const ex=E.buildExport({padding:1,trim:true});
  const j=ex.skeleton;
  const expBox=window.__placed.map(p=>p.x+','+p.y+' '+p.w+'x'+p.h).sort();
  const gotBox=Object.keys(j.skins.default).map(n=>{const a=j.skins.default[n][n];
    return Math.round(a.x-a.width/2)+','+Math.round(E.S.h-(a.y+a.height/2))+' '+a.width+'x'+a.height;}).sort();
  return '导出部件='+ex.parts.length+' · 由导出的 JSON 反推回图片位置比对='+(JSON.stringify(expBox)===JSON.stringify(gotBox) ? '完全一致 ✅' : '不一致\n exp:'+expBox.join('|')+'\n got:'+gotBox.join('|'));
})()

(async()=>{
  const E=window.CutterEngine;
  const ex=E.buildExport({padding:1,trim:true});
  const names=ex.parts.map(p=>p.name);
  const t0=performance.now();
  try {
    const r=await API.cutterExport({id:'zz_test_grid', parts:ex.parts, skeleton:ex.skeleton, overwrite:true});
    return '导出: '+JSON.stringify(r)+' · '+names.length+' 个部件 · '+(performance.now()-t0).toFixed(0)+'ms';
  } catch(e){ return '导出失败: '+e.message; }
})()

